		pts, err := FetchUserBonuses(gCtx)
		if err != nil {
			return err
		}
		mu.Lock()
		dashData.Bonuses = pts
		mu.Unlock()
		return nil
	})

	if err := g.Wait(); err != nil {
		return nil, err
	}

	return &dashData, nil
